#!/usr/bin/env python3
from pathlib import Path
import sys,zlib,base64
root=Path(sys.argv[1])
p=root/'app/src/main/java/ru/printcheck/android/ReadOnlyHttp.java'
s=p.read_text(encoding='utf-8')
a=s.index('    static JSONObject parseMaketsPopup')
b=s.index('    private static JSONArray dedupe',a)
new=zlib.decompress(base64.b64decode('')).decode('utf-8')
p.write_text(s[:a]+new+s[b:],encoding='utf-8')
bg=root/'app/build.gradle'
t=bg.read_text(encoding='utf-8').replace('versionCode 300005','versionCode 300006').replace("versionName '3.1.0-alpha2'","versionName '3.1.0-alpha3'")
bg.write_text(t,encoding='utf-8')
print('alpha3 parser patch applied')
